let bcc_recipients = if !self.bcc_recipients.is_empty() {
    Some(ArrayOfRecipients(
        self.bcc_recipients
            .iter()
            .map(|mailbox| Recipient {
                mailbox: ews::Mailbox {
                    name: mailbox.name.clone(),
                    email_address: mailbox.email_address.clone(),
                    ..Default::default()
                },
            })
            .collect(),
    ))
} else {
    None
};
